function buildMonthlySchedule() { const month = isoToday.slice(0, 7); const daysInMonth = new Date(today.getFullYear(), today.getMonth() + 1, 0).getDate(); const shiftKeys = Object.keys(shifts); const days = []; for (let day = 1; day <= daysInMonth; day += 1) { const date = `${month}-${String(day).padStart(2, '0')}`; const weekday = new Date(`${date}T00:00:00`).getDay(); const ordered = [...employeeData].sort((left, right) => left.id - right.id); const assignments = ordered.map((person, index) => ({ employeeId: person.id, shift: weekday === person.weeklyOffDay ? 'off' : shiftKeys[(day + index) % shiftKeys.length] })); days.push({ date, assignments }); } return { month, days }; }
