const scheduledAssignment = (person, date) => monthlySchedule.days.find(day => day.date === date)?.assignments.find(assignment => assignment.employeeId === person.id);
const monthKey = date => date.slice(0, 7);
const dayNumber = date => new Date(`${date}T00:00:00`).getDay();
const isScheduledWorkday = (date, offDay) => dayNumber(date) !== offDay;
const dayName = day => ['Minggu', 'Senin', 'Selasa', 'Rabu', 'Kamis', 'Jumat', 'Sabtu'][day];
const attendanceStats = person => { const currentMonth = isoToday.slice(0, 7); const offDay = Number.isInteger(Number(person.weeklyOffDay)) ? Number(person.weeklyOffDay) : weeklyOffDay; const records = attendance.filter(record => record.id === person.id && monthKey(record.date || isoToday) === currentMonth && record.status === 'present'); const workdays = new Set(records.filter(record => isScheduledWorkday(record.date || isoToday, offDay) || dayNumber(record.date || isoToday) === offDay || record.replacement).map(record => record.date || isoToday)); const weekendDays = new Set(records.filter(record => [0, 6].includes(dayNumber(record.date || isoToday))).map(record => record.date || isoToday)); const daysInMonth = new Date(today.getFullYear(), today.getMonth() + 1, 0).getDate(); let expectedWorkdays = 0; for (let day = 1; day <= daysInMonth; day += 1) { const date = `${currentMonth}-${String(day).padStart(2, '0')}`; if (isScheduledWorkday(date, offDay)) expectedWorkdays += 1; } return { attendedWorkdays: workdays.size, weekendDays: weekendDays.size, expectedWorkdays, offDay }; };
const payroll = person => { const stats = attendanceStats(person); const automatic = { fixedSalary: person.fixedSalary / stats.expectedWorkdays * stats.attendedWorkdays, mealTransport: 10000 * stats.attendedWorkdays, weekend: person.weekendAllowance * stats.weekendDays, attendanceBonus: stats.attendedWorkdays === stats.expectedWorkdays ? person.attendanceBonus : 0, overtime: person.overtimeRate * person.overtimeHours, otherAdjustment: person.otherAdjustment }; const values = { ...automatic, ...(person.manualPayroll || {}) }; return { ...stats, ...values, automatic, isManual: Boolean(person.manualPayroll), net: values.fixedSalary + values.weekend + values.mealTransport + values.attendanceBonus + values.overtime + values.otherAdjustment }; };
const money = value => `Rp ${Number(value).toLocaleString('id-ID')}`;
const reportDate = date => new Date(`${date}T00:00:00`).toLocaleDateString('id-ID', { day: '2-digit', month: 'short', year: 'numeric' });
const reportDefaults = () => { const end = isoToday; const startDate = new Date(`${end}T00:00:00`); startDate.setDate(startDate.getDate() - 29); return { start: startDate.toISOString().slice(0, 10), end }; };
const minutesNow = () => { const now = new Date(); return now.getHours() * 60 + now.getMinutes(); };
const minutesFromTime = value => { const [hours, minutes] = value.split(':').map(Number); return hours * 60 + minutes; };
let replacementMode = false;
const checkShiftWindow = (person, action, replacement = replacementMode) => { const daily = scheduledAssignment(person, isoToday); const assignedShift = daily?.shift && daily.shift !== 'off' ? daily.shift : person.shift; const shift = shifts[assignedShift] || shifts.pagi; const current = minutesNow(); const start = minutesFromTime(shift.start); const end = minutesFromTime(shift.end); const earliestIn = start - 60; const latestOut = end + 120; if (action === 'in' && new Date().getDay() === Number(person.weeklyOffDay) && !replacement) throw new Error(`Hari ini hari libur personal kamu (${dayName(Number(person.weeklyOffDay))}). Centang masuk sebagai pengganti jika ditugaskan.`); const valid = action === 'in' ? current >= earliestIn && current <= end : current >= start && current <= latestOut; if (!valid) { const period = action === 'in' ? `${shift.start}–${shift.end}` : `${shift.start}–${String(Math.floor(latestOut / 60)).padStart(2, '0')}:${String(latestOut % 60).padStart(2, '0')}`; throw new Error(`Di luar jam ${shift.label}. Waktu ${action === 'in' ? 'masuk' : 'pulang'} yang diizinkan ${period}.`); } };
