const initials = name => name.split(' ').map(part => part[0]).slice(0, 2).join('');
const distanceInMeters = (from, to) => { const earthRadius = 6371000; const latitudeDelta = (to.latitude - from.latitude) * Math.PI / 180; const longitudeDelta = (to.longitude - from.longitude) * Math.PI / 180; const latitudeOne = from.latitude * Math.PI / 180; const latitudeTwo = to.latitude * Math.PI / 180; const a = Math.sin(latitudeDelta / 2) ** 2 + Math.cos(latitudeOne) * Math.cos(latitudeTwo) * Math.sin(longitudeDelta / 2) ** 2; return earthRadius * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a)); };
const parseMapsCoordinates = value => { const match = value.match(/@(-?\d+(?:\.\d+)?),\s*(-?\d+(?:\.\d+)?)/) || value.match(/(?:q|query|place)=[^/]*?(-?\d+(?:\.\d+)?),\s*(-?\d+(?:\.\d+)?)/) || value.match(/(-?\d{1,3}\.\d+),\s*(-?\d{1,3}\.\d+)/); return match ? { latitude: Number(match[1]), longitude: Number(match[2]) } : null; };
const getCurrentPosition = () => new Promise((resolve, reject) => { if (!navigator.geolocation) { reject(new Error('Perangkat tidak mendukung GPS.')); return; } navigator.geolocation.getCurrentPosition(resolve, () => reject(new Error('Izin lokasi diperlukan untuk absensi.')), { enableHighAccuracy: true, timeout: 10000, maximumAge: 0 }); });
const checkClubDistance = async () => { if (!clubLocations.length) throw new Error('Lokasi club belum diatur oleh admin.'); const position = await getCurrentPosition(); const current = { latitude: position.coords.latitude, longitude: position.coords.longitude }; const distances = clubLocations.map(location => distanceInMeters(location, current)); const nearestIndex = distances.indexOf(Math.min(...distances)); const nearest = distances[nearestIndex]; const allowedRadius = clubLocations[nearestIndex].radius; if (nearest > allowedRadius) throw new Error(`Kamu berada sekitar ${Math.round(nearest)} meter dari lokasi club terdekat. Radius lokasi ini ${allowedRadius} meter.`); return nearest; };
function renderLocationStatus() { const title = document.querySelector('#locationTitle'); const status = document.querySelector('#locationStatus'); const list = document.querySelector('#locationList'); if (!title || !status || !list) return; title.textContent = clubLocations.length ? `${clubLocations.length} lokasi absensi aktif` : 'Lokasi club belum diatur'; status.textContent = clubLocations.length ? 'Clock in/out diterima dari radius sesuai masing-masing titik.' : 'Admin harus mengatur lokasi saat berada di venue.'; list.innerHTML = clubLocations.map((location, index) => `<span class="location-chip" title="${location.latitude}, ${location.longitude}">${location.name} · ${location.radius}m <button type="button" data-remove-location="${index}" title="Hapus lokasi">×</button></span>`).join(''); document.querySelector('#locationBanner')?.classList.toggle('configured', Boolean(clubLocations.length)); document.querySelector('#setLocationButton').disabled = clubLocations.length >= 2; document.querySelector('#setLocationButton').textContent = clubLocations.length >= 2 ? '⌖ Maks. 2 lokasi' : '⌖ Tambah lokasi'; }
function renderShiftSettings() { const container = document.querySelector('#shiftSettingsGrid'); if (!container) return; container.innerHTML = Object.entries(shifts).map(([key, shift]) => `<div class="shift-setting-card ${key}"><b>Shift ${shift.label}</b><span>${key === 'midle' ? 'Shift tengah / malam' : `Periode kerja shift ${shift.label.toLowerCase()}`}</span><label>Mulai<input type="time" data-shift-key="${key}" data-shift-part="start" value="${shift.start}"></label><label>Selesai<input type="time" data-shift-key="${key}" data-shift-part="end" value="${shift.end}"></label></div>`).join(''); }
const daysLeft = date => Math.ceil((new Date(`${date}T23:59:59`) - new Date()) / 86400000);
const memberState = member => { const days = daysLeft(member.expires); return days < 0 ? 'expired' : days <= 7 ? 'expiring' : 'active'; };
