function renderMonthlySchedule() { const monthLabel = new Date(`${monthlySchedule.month}-01T00:00:00`).toLocaleDateString('id-ID', { month: 'long', year: 'numeric' }); const label = document.querySelector('#scheduleMonthLabel'); const head = document.querySelector('#monthlyScheduleHead'); const body = document.querySelector('#monthlyScheduleBody'); const balance = document.querySelector('#scheduleBalance'); if (!label || !head || !body || !balance) return; label.textContent = monthLabel; head.innerHTML = `<tr><th>Tanggal</th>${employeeData.map(person => `<th>${person.name}</th>`).join('')}</tr>`; body.innerHTML = monthlySchedule.days.map(day => { const date = new Date(`${day.date}T00:00:00`); const assignments = employeeData.map(person => { const assignment = day.assignments.find(item => item.employeeId === person.id); const text = assignment?.shift === 'off' ? 'Libur' : shifts[assignment?.shift]?.label || '-'; return `<td><span class="schedule-cell ${assignment?.shift === 'off' ? 'off' : assignment?.shift}">${text}</span></td>`; }).join(''); return `<tr><td><b>${date.toLocaleDateString('id-ID', { day: '2-digit' })}</b><small>${dayName(date.getDay())}</small></td>${assignments}</tr>`; }).join(''); balance.innerHTML = employeeData.map(person => { const counts = monthlySchedule.days.reduce((result, day) => { const shift = day.assignments.find(item => item.employeeId === person.id)?.shift || 'off'; result[shift] = (result[shift] || 0) + 1; return result; }, {}); return `<div class="balance-card"><b>${person.name}</b><span>Pagi ${counts.pagi || 0} · Siang ${counts.siang || 0} · Malam ${counts.midle || 0} · Libur ${counts.off || 0}</span></div>`; }).join(''); }
